{"script": "(function(outputs, steps, stepResult, assertEqual) {
 var out = new CadastrarClienteUseCase().execute({
 nome: 'Cliente T1', email: 't1@teste.com', telefone: '11988887777',
 consentimentoLgpd: true, consentimentoVersao: 'v1.0',
 consentimentoFinalidade: 'Agendamento de sessões'
 });
 var cli = new GlideRecord('x_espaco_cliente');
 cli.get(out.sys_id);
 assertEqual({ name: 'consentimento registrado', shouldbe: 'true', value: cli.getValue('consentimento_lgpd') });
})(outputs, steps, stepResult, assertEqual);"}
